def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in into s_out."""
    # Simple approach: find first position where chars differ
    min_len = min(len(s_in), len(s_out))

    # Check for insertion/deletion
    if len(s_in) != len(s_out):
        # Look for one character difference
        for i in range(min_len):
            if s_in[i] != s_out[i]:
                # Check if removing from s_in or inserting into s_in works
                if len(s_in) > len(s_out):
                    # Character removed
                    return s_in[i], "", i
                else:
                    # Character inserted  
                    return "", s_out[i], i
        # If we got here, one string is prefix of other
        if len(s_in) > len(s_out):
            return s_in[min_len], "", min_len
        else:
            return "", s_out[min_len], min_len

    # Same length - look for first differing character
    for i in range(len(s_in)):
        if s_in[i] != s_out[i]:
            return s_in[i], s_out[i], i
    return "", "", -1  # No difference

# Analyze each changed pair
changed = [(2, 'afag', 'adg'), (3, 'gfccju', 'gcfccju')]

for idx, s_in, s_out in changed:
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    print(f"Pair {idx}: '{s_in}' -> '{s_out}'")
    print(f"  Minimal edit: replace '{old_sub}' with '{new_sub}' at position {pos}")
    print()

