def propose_rule_candidates(s_in, s_out):
    """Propose possible rule candidates from a transformation."""
    # For simplicity, let's make basic candidates based on the minimal edit
    candidates = []

    # Find the minimal edit
    min_len = min(len(s_in), len(s_out))

    # Check for insertion/deletion
    if len(s_in) != len(s_out):
        # Look for one character difference
        for i in range(min_len):
            if s_in[i] != s_out[i]:
                if len(s_in) > len(s_out):
                    # Character removed - pattern is the character, replacement is empty
                    candidates.append((s_in[i], ""))
                else:
                    # Character inserted - pattern is empty, replacement is the char
                    candidates.append(("", s_out[i]))
                break
        # If we got to the end, it's a suffix difference
        if len(s_in) > len(s_out):
            candidates.append((s_in[min_len], ""))
        else:
            candidates.append(("", s_out[min_len]))
    else:
        # Same length - look for first differing character
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                candidates.append((s_in[i], s_out[i]))
                break

    # Add more general candidates
    if len(s_in) == len(s_out) and len(s_in) >= 2:
        # Try longer patterns
        for length in range(min(3, len(s_in)), 0, -1):
            if length <= len(s_in):
                pattern = s_in[:length]
                replacement = s_out[:length]
                if pattern != replacement:
                    candidates.append((pattern, replacement))

    return candidates

def find_over_applications(inputs, outputs, rules):
    """Check if rules over-apply to any inputs."""
    # Apply rules to all inputs and check if any produce wrong outputs
    applied = []
    for inp in inputs:
        result = inp
        for pattern, replacement in rules:
            result = result.replace(pattern, replacement)
        applied.append(result)

    over_apps = []
    for i, (inp, expected) in enumerate(zip(inputs, outputs)):
        if applied[i] != expected:
            over_apps.append((i, inp, applied[i]))

    return over_apps

# Analyze each changed pair
changed = [(2, 'afag', 'adg'), (3, 'gfccju', 'gcfccju')]

rules = []

for idx, s_in, s_out in changed:
    print(f"\nAnalyzing pair {idx}: '{s_in}' -> '{s_out}'")

    candidates = propose_rule_candidates(s_in, s_out)
    print(f"Candidates: {candidates}")

    # Try each candidate
    for pattern, replacement in candidates:
        temp_rules = rules + [(pattern, replacement)]
        over_apps = find_over_applications(inputs, outputs, temp_rules)

        print(f"  Trying rule: replace('{pattern}', '{replacement}')")
        print(f"    Over-applications: {over_apps}")

        if not over_apps:
            print("    ✓ This rule doesn't over-apply!")
            rules.append((pattern, replacement))
            break
        else:
            print("    ✗ This rule over-applies")

